def create_spark_schema(entity_name: str):
    logInfo(
        f"Creating Spark schema for entity={entity_name}"
    )

    schema_output = mssparkutils.notebook.run(
        "/py_create_spark_schema",
        30,
        {
            "db_name": "odw_standardised_db",
            "entity_name": entity_name
        }
    )

    schema_json = json.loads(schema_output) if schema_output else {}

    if schema_json.get("schema"):
        spark_schema = StructType.fromJson(
            json.loads(schema_json["schema"])
        )
        logInfo(
            f"Spark schema created for entity={entity_name}"
        )
        return spark_schema

    logInfo(
        f"No schema returned for entity={entity_name}"
    )
    return ""

