def read_raw_messages(
    source_path: str,
    last_ingest_time,
    entity_name: str,
    watermark_column: str,
    spark_schema
) -> DataFrame:
    logInfo(
        f"Reading raw messages for entity={entity_name} "
        f"from {source_path}"
    )

    reader = (
        spark.read
        .option("multiline", "true")
        .option("recursiveFileLookup", "true")
    )

    if last_ingest_time:
        try:
            wm_dt = datetime.strptime(
                last_ingest_time[:19],
                "%Y-%m-%d %H:%M:%S"
            )

            buffer_dt = wm_dt - timedelta(days=1)

            modified_after_str = buffer_dt.strftime(
                "%Y-%m-%dT%H:%M:%S"
            )

            reader = reader.option(
                "modifiedAfter",
                modified_after_str
            )

            logInfo(
                f"modifiedAfter filter applied for {entity_name}: "
                f"{modified_after_str}"
            )

        except Exception as parse_err:
            logInfo(
                f"Could not parse watermark for {entity_name}; "
                f"reading all files: {parse_err}"
            )

    if spark_schema:
        reader = reader.schema(spark_schema)

    try:
        df = reader.json(source_path)

    except Exception as e:
        logInfo(
            f"No files found or error reading {source_path} "
            f"for {entity_name}: {e}"
        )

        return (
            spark.createDataFrame([], schema=spark_schema)
            if spark_schema
            else spark.createDataFrame([], StructType())
        )

    df = df.withColumns(
        {
            "expected_from": F.current_timestamp(),
            "expected_to": F.expr(
                "current_timestamp() + INTERVAL 1 DAY"
            ),
            "ingested_datetime": F.to_timestamp(
                watermark_column
            ),
            "input_file": F.input_file_name()
        }
    )

    logInfo(
        f"Raw messages read for entity={entity_name}"
    )

    return df

from odw.core.anonymisation.engine import AnonymisationEngine
from odw.core.anonymisation.config import (
    load_config,
    AnonymisationConfig
)
from odw.core.util.util import Util


def apply_anonymisation_sb(
    df: DataFrame,
    entity_name: str
) -> DataFrame:
    anon_enabled = Util.is_non_production_environment()

    logInfo(
        f"anonymisation_gate: "
        f"environment={Util.get_environment()}, "
        f"enabled={anon_enabled}, "
        f"entity={entity_name}"
    )

    if not anon_enabled:
        return df

    anon_config = AnonymisationConfig()

    try:
        policy_path = (
            f"abfss://odw-config@{storage_account}"
            "anonymisation/policy.yaml"
        )

        policy_text = (
            spark.read
            .text(policy_path, wholetext=True)
            .first()
            .value
        )

        anon_config = load_config(text=policy_text)

    except Exception as config_err:
        logInfo(
            f"Could not load anonymisation policy for "
            f"{entity_name}; using defaults: {config_err}"
        )

    engine = AnonymisationEngine(
        config=AnonymisationConfig(
            classification_allowlist=(
                anon_config.classification_allowlist
            ),
            seed_column=anon_config.get_seed_column(
                entity_name
            )
        )
    )

    logInfo(
        f"Applying anonymisation for entity={entity_name}"
    )

    return engine.apply_from_purview(
        df,
        entity_name=entity_name,
        source_folder="ServiceBus"

